/**
 * The generated-tree constants and the one generated file TypeScript still writes.
 *
 * The Rust compiler emits the whole tree (`crates/flamme-core/src/emit.rs`); these
 * are the members the TypeScript side also names. `emitTsconfig` exists because the
 * Vite plugin writes `.flamme/tsconfig.json` during its `config` hook, before any
 * codegen run has produced the tree, so a project can be type-checked before its
 * first compile.
 */

/** Compiler version stamped into `manifest.json` and `runtime/index.ts`. */
export const COMPILER_VERSION = '0.0.0';

/** Runtime version stamped into `manifest.json` and `runtime/index.ts`. */
export const RUNTIME_VERSION = '0.0.0';

/**
 * The banner every generated TypeScript module starts with, as its first line.
 *
 * One convention, no exceptions: an artifact, `index.ts`, `runtime/index.ts`,
 * `props.ts`, `graphql/*.ts` and `ambient.d.ts` all open with exactly this text.
 * The JSON members of the tree (`tsconfig.json`, `manifest.json`,
 * `persisted.json`) cannot carry a JSDoc block, and `schema.graphql` is the
 * project's own SDL passed through verbatim; those four carry their provenance in
 * their own format instead (`manifest.json` and `persisted.json` name the
 * compiler version, `tsconfig.json` is regenerated on every run, and the SDL is
 * what the server serves). `packages/core/test/banner.test.ts` pins the closed
 * set, so a new generated file cannot skip the banner by accident.
 */
export const GENERATED_BANNER =
  '/** This file is automatically generated by Flamme. Do not edit. */';

/**
 * The generated `tsconfig.json`, verbatim from §2.4.
 *
 * The Rust emitter prints the same object (`emit_tsconfig` in
 * `crates/flamme-core/src/emit.rs`); `packages/core/test/generated-tsconfig.test.ts`
 * pins the two to the same bytes.
 */
export function emitTsconfig(): string {
  const config = {
    compilerOptions: {
      baseUrl: '.',
      paths: { $flamme: ['./index.ts'], '$flamme/*': ['./*'] },
      rootDirs: ['..', '.'],
      target: 'ES2023',
      lib: ['ES2023'],
      module: 'ESNext',
      moduleResolution: 'bundler',
      moduleDetection: 'force',
      resolveJsonModule: true,
      types: [],
      strict: true,
      noUncheckedIndexedAccess: true,
      exactOptionalPropertyTypes: true,
      noImplicitOverride: true,
      noImplicitReturns: true,
      noFallthroughCasesInSwitch: true,
      noUnusedLocals: true,
      noUnusedParameters: true,
      useUnknownInCatchVariables: true,
      verbatimModuleSyntax: true,
      isolatedModules: true,
      noEmit: true,
      skipLibCheck: true,
      forceConsistentCasingInFileNames: true,
    },
    include: [
      'ambient.d.ts',
      'index.ts',
      'props.ts',
      'runtime/index.ts',
      'artifacts/**/*.ts',
      'graphql/**/*.ts',
      '../src/**/*.ts',
      '../src/**/*.vue',
      '../test/**/*.ts',
      '../vite.config.ts',
    ],
  };
  return `${JSON.stringify(config, null, 2)}\n`;
}
